import { Plugin } from 'vite';

/**
 * Vite 插件：在 `vite dev` 期间将 @sentry/react 重定向到 stub。
 *
 * - apply: 'serve' → 仅在开发服务器模式下生效
 * - 生产构建时 @sentry/react 正常解析，使用真实 DSN 上报
 */

declare function withSentryStub(): Plugin;

/**
 * 生产构建使用的 Sentry 替换插件。
 *
 * 只负责在模块解析阶段把 `@sentry/react` 指向 noop stub，不扫描或限制业务代码
 * 使用的 Sentry API，避免监控代码的写法变化阻塞应用发布。
 */
declare function withSentryBuild(): Plugin;

/**
 * 云端 dev server 专用：HMR 开关 + 手动 reload 控制接口。
 *
 * 暴露三个内部 HTTP 接口：
 *   POST /innerapi/v1/sourcecode/__hmr_off    — 暂停 HMR 推送
 *   POST /innerapi/v1/sourcecode/__hmr_on     — 恢复 HMR 推送
 *   POST /innerapi/v1/sourcecode/__hmr_reload — 触发一次全页 full-reload
 *
 * 同时注入 virtual:after-update 模块，使 vite:afterUpdate 事件可被宿主页面监听。
 */
declare function hmrTogglePlugin(): Plugin;

/**
 * extractRouterPlugin：Vite 插件入口。
 *
 * 功能概述：
 * 在 Vite dev server（serve 模式）下，通过 AST 静态分析实时收集项目路由信息，
 * 并通过 /__routes HTTP 接口暴露给开发调试面板（devtools）使用。
 *
 * 路由收集方式（均在 transform 钩子中实时处理每个文件）：
 * 1. JSX 路由：解析含 <Route> 的任意组件文件（包括 .map() 动态渲染）
 * 2. Hook 路由：解析含 useRoutes() 调用的文件
 *
 * 跨文件嵌套路由处理：
 * 当遇到 <Route path="/admin/*" element={<AdminPanel />} /> 时，记录通配符挂载关系。
 * 在 rebuildRoutes 阶段，对挂载目标文件中的相对路径路由追加正确前缀。
 * 支持一级间接引用（通过 Vite moduleGraph 追踪 element 文件的直接 import）。
 *
 * 插件配置：
 * - apply: 'serve' → 仅在开发模式生效
 * - enforce: 'pre' → 在其他插件之前执行 transform
 */

/**
 * 创建路由收集 Vite 插件实例。
 *
 * @returns Vite Plugin 对象
 *
 * @example
 * // vite.config.ts
 * import { extractRouterPlugin } from '@miaoda/devkit';
 * export default defineConfig({
 *   plugins: [extractRouterPlugin()],
 * });
 */
declare const extractRouterPlugin: () => Plugin;

export { extractRouterPlugin, hmrTogglePlugin, withSentryBuild, withSentryStub };
